import math

def split_bill(total_amount: float, num_people: int) -> list[float]:
    if num_people <= 0:
        raise ValueError("num_people must be a positive integer")
    if total_amount < 0:
        raise ValueError("total_amount must be non-negative")

    # Convert to cents using rounding to avoid floating-point drift
    total_cents = round(total_amount * 100)

    base = total_cents // num_people
    remainder = total_cents % num_people

    result = []
    for i in range(num_people):
        if i < remainder:
            amount_cents = base + 1
        else:
            amount_cents = base
        result.append(amount_cents / 100.0)

    return result

def split_bill(total_amount: float, num_people: int) -> list[float]:
    # Convert to integer cents to avoid floating-point errors
    total_cents = int(round(total_amount * 100))
    base_cents = total_cents // num_people
    remainder = total_cents % num_people

    # Build the list: `remainder` people get one extra cent
    return [
        base_cents / 100.0 + (1.0 / 100.0 if i < remainder else 0.0)
        for i in range(num_people)
    ]

