def split_bill(total_amount: float, num_people: int) -> list[float]:
    if total_amount < 0:
        raise ValueError("total_amount must be non-negative")
    if not isinstance(num_people, int) or num_people <= 0:
        raise ValueError("num_people must be a positive integer")

    # Convert to cents and round to the nearest cent
    total_cents = round(total_amount * 100)

    # Base share per person in cents (integer division)
    base_share = total_cents // num_people
    remainder = total_cents % num_people

    # Build the list: first `remainder` people get one extra cent
    result = []
    for i in range(num_people):
        if i < remainder:
            result.append(base_share + 1)
        else:
            result.append(base_share)

    # Convert back to dollars as floats rounded to two decimal places
    return [c / 100.0 for c in result]
